function lps(str) {
    const n = str.length;
    const dp = Array.from({ length: n }, () => Array(n).fill(0));

    for (let length = 1; length <= n; length++) {
        for (let i = 0; i <= n - length; i++) {
            const j = i + length - 1;
            if (length === 1) {
                dp[i][j] = 1;
            } else if (length === 2 && str[i] === str[j]) {
                dp[i][j] = 2;
            } else if (str[i] === str[j]) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                dp[i][j] = Math.max(dp[i][j - 1], dp[i + 1][j]);
            }
        }
    }

    return dp[0][n - 1];
}

function lps(str){
    let n = str.length;
    let dp = Array.from(Array(n), () => Array(n).fill(0));

    for (let i = 0; i < n; i++) {
        dp[i][i] = 1;
    }

    for (let cl = 2; cl <= n; cl++) {
        for (let i = 0; i < n - cl + 1; i++) {
            let j = i + cl - 1;
            if (str[i] === str[j] && cl === 2) {
                dp[i][j] = 2;
            } else if (str[i] === str[j]) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                dp[i][j] = Math.max(dp[i][j - 1], dp[i + 1][j]);
            }
        }
    }

    return dp[0][n - 1];
}

