function amicable_numbers_sum(limit){
    function sum_of_divisors(n) {
        let sum = 1;
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let sum = 0;
    for (let i = 2; i < limit; i++) {
        let a = sum_of_divisors(i);
        if (a > i && sum_of_divisors(a) === i) {
            sum += i + a;
        }
    }
    return sum;
}

function amicable_numbers_sum(limit){
