        let sum = 1;
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let amicableSum = 0;
    for (let num = 2; num <= limit; num++) {
        let divSum = sum_of_divisors(num);
        if (divSum !== num && sum_of_divisors(divSum) === num) {
            amicableSum += num;
        }
    }
    return amicableSum;
}

