function find_Index(n) {
  // Calculate the lower bound for the smallest n-digit number
  const lowerBound = 10 ** (n - 1);
  // Calculate the upper bound for the largest n-digit number
  const upperBound = 10 ** n - 1;

  // Initialize the variable to store the index of the smallest triangular number with n digits
  let index = -1;

  // Iterate through the possible values of n-digit numbers
  for (let i = 1; index === -1; i++) {
    // Calculate the i-th triangular number
    const triangularNumber = (i * (i + 1)) / 2;

    // Check if the triangular number has n digits
    if (triangularNumber >= lowerBound && triangularNumber <= upperBound) {
      // Update the index
      index = i;
    }
  }

  // Return the index of the smallest triangular number with n digits
  return index;
}

function find_Index(n){
