    let result = -1;

    while (lower <= upper) {
        let mid = Math.floor((lower + upper) / 2);
        let triangularNumber = (mid * (mid + 1)) / 2;
        let numDigits = triangularNumber.toString().length;

        if (numDigits === n) {
            result = mid;
            upper = mid - 1; // Try for a smaller index
        } else if (numDigits < n) {
            lower = mid + 1; // Increase the lower bound
        } else {
            upper = mid - 1; // Decrease the upper bound
        }
    }

    return result;
}

