    function fib(num) {
        if (num <= 1) return num;
        let a = 0, b = 1, c = 1;
        for (let i = 2; i < num; i++) {
            c = a + b;
            a = b;
            b = c;
        }
        return c;
    }

    let count = 0;
    let i = 1;
    while (true) {
        let fibNumber = fib(i);
        if (isPrime(fibNumber)) {
            count++;
            if (count === n) return fibNumber;
        }
        i++;
    }
}

