function heap_sort(iterable) {
  let n = iterable.length;

  // Build a max heap.
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    heapify(iterable, n, i);
  }

  // One by one extract elements
  for (let i = n - 1; i > 0; i--) {
    [iterable[0], iterable[i]] = [iterable[i], iterable[0]]; // swap
    heapify(iterable, i, 0);
  }

  return iterable;
}

function heapify(iterable, n, i) {
  let largest = i; // Initialize largest as root
  let left = 2 * i + 1; // left = 2*i + 1
  let right = 2 * i + 2; // right = 2*i + 2

  // If left child is larger than root
  if (left < n && iterable[left] > iterable[largest]) {
    largest = left;
  }

  // If right child is larger than largest so far
  if (right < n && iterable[right] > iterable[largest]) {
    largest = right;
  }

  // If largest is not root
  if (largest !== i) {
    [iterable[i], iterable[largest]] = [iterable[largest], iterable[i]]; // swap

    // Recursively heapify the affected sub-tree
    heapify(iterable, n, largest);
  }
}

function heap_sort(iterable) {
    let n = iterable.length;

    // Build max heap
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
        heapify(iterable, n, i);
    }

    // Extract elements from heap
    for (let i = n - 1; i > 0; i--) {
        // Move current root to end
        [iterable[0], iterable[i]] = [iterable[i], iterable[0]];

        // Call max heapify on the reduced heap
        heapify(iterable, i, 0);
    }

    return iterable;
}

