function pancake_sort(nums) {
    function flip(subArray, k) {
        let start = 0;
        let end = k;
        while (start < end) {
            let temp = subArray[start];
            subArray[start] = subArray[end];
            subArray[end] = temp;
            start++;
            end--;
        }
    }

    let n = nums.length;
    for (let i = n - 1; i >= 0; i--) {
        let maxIndex = i;
        for (let j = 0; j < i; j++) {
            if (nums[j] > nums[maxIndex]) {
                maxIndex = j;
            }
        }
        if (maxIndex !== i) {
            flip(nums, maxIndex);
            flip(nums, i);
        }
    }
    return nums;
}

function pancake_sort(nums) {
    function flip(subArray, k) {
        let temp;
        let start = 0;
        let end = k;
        while (start < end) {
            temp = subArray[start];
            subArray[start] = subArray[end];
            subArray[end] = temp;
            start++;
            end--;
        }
    }

    let size = nums.length;
    while (size > 1) {
        // Find the index of the maximum element in nums
        let maxIndex = 0;
        for (let i = 1; i < size; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }

        // Flip the maximum element to the beginning if it's not already
        if (maxIndex !== size - 1) {
            flip(nums, maxIndex);
            flip(nums, size - 1);
        }

        size--;
    }

    return nums;
}

