function findFirst(arr, x, n) {
  let low = 0, high = n - 1;
  while (high >= low) {
    let mid = low + Math.floor((high - low) / 2);
    if ((mid == 0 || x > arr[mid - 1]) && (arr[mid] == x)) {
      return mid;
    } else if (x > arr[mid]) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return -1;
}

