function max_sum(arr) {
    let n = arr.length;
    let inc = new Array(n).fill(0);
    let dec = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        inc[i] = dec[i] = arr[i];
    }

    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && inc[i] < inc[j] + arr[i]) {
                inc[i] = inc[j] + arr[i];
            }
        }
    }

    for (let i = n - 2; i >= 0; i--) {
        for (let j = n - 1; j > i; j--) {
            if (arr[i] > arr[j] && dec[i] < dec[j] + arr[i]) {
                dec[i] = dec[j] + arr[i];
            }
        }
    }

    let maxSum = 0;
    for (let i = 0; i < n; i++) {
        if (maxSum < inc[i] + dec[i] - arr[i]) {
            maxSum = inc[i] + dec[i] - arr[i];
        }
    }

    return maxSum;
}

function max_sum(arr) {
