    let lis = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        lis[i] = arr[i];
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && lis[i] < lis[j] + arr[i]) {
                lis[i] = lis[j] + arr[i];
            }
        }
    }

    let lds = new Array(n).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        lds[i] = arr[i];
        for (let j = n - 1; j > i; j--) {
            if (arr[i] > arr[j] && lds[i] < lds[j] + arr[i]) {
                lds[i] = lds[j] + arr[i];
            }
        }
    }

    let maxSum = 0;
    for (let i = 0; i < n; i++) {
        maxSum = Math.max(maxSum, lis[i] + lds[i] - arr[i]);
